 await test('N-way explicit trial exactly one shared guard/audit/nonce winner',async()=>{const s=await signedIn();const g=guard(s);const results=await Promise.all(Array.from({length:10},(_,i)=>start(s,'race'+i,initial,{...g,commitNonce:'trial-'+i})));assert.equal(results.filter(r=>r.status===200&&r.body.outcome==='started').length,1);assert.ok(results.every(r=>[200,409].includes(r.status)));const source=rows(`SELECT * FROM entitlement_sources WHERE account_id='${s.accountID}'`)[0];assert.equal(source.trial_started_at,initial);assert.equal(source.trial_ends_at,initial+1209600);const current=rows(`SELECT * FROM account_guard WHERE account_id='${s.accountID}'`)[0];assert.equal(current.account_revision,Number(g.accountRevision)+1);const audit=rows(`SELECT * FROM account_audit WHERE account_id='${s.accountID}' AND action='trial-start'`);assert.equal(audit.length,1);assert.equal(audit[0].commit_nonce,current.commit_nonce);assert.equal(rows(`SELECT entitlement_revision FROM accounts WHERE account_id='${s.accountID}'`)[0].entitlement_revision,1);});
 await test('exact retry replays stored response, changed hash refuses, another key never redates',async()=>{const s=await signedIn();const g=guard(s);const a=await start(s,'same',initial,g);assert.equal(a.status,200);const before=snapshot();const replay=await start(s,'same',initial+1,g);assert.deepEqual(replay,a);assert.deepEqual(snapshot(),before);assert.equal((await start(s,'same',initial+1,g,'e'.repeat(64))).status,409);const next=await start(s,'next',initial+1);assert.equal(next.body.outcome,'existing');assert.equal(next.body.startedAt,initial);assert.equal(next.body.expiresAt,initial+1209600);});
 await test('active beta refusal changes no history; beta end preserves full future trial',async()=>{const s=await signedIn();d1(['--command',`INSERT INTO entitlement_sources(account_id,beta_invited,beta_ends_at) VALUES('${s.accountID}',1,${initial+60});`]);const before=snapshot();const r=await start(s);assert.equal(r.status,409);assert.deepEqual(r.body,{outcome:'trial-unavailable-during-beta'});assert.deepEqual(snapshot(),before);const after=await start(s,'after-beta',initial+60);assert.equal(after.status,200);assert.equal(after.body.startedAt,initial+60);assert.equal(after.body.expiresAt,initial+60+1209600);});
