 await test('audit failure atomically rolls back trial and retry receipt',async()=>{const s=await signedIn();d1(['--command',"CREATE TRIGGER s1b_fail_audit BEFORE INSERT ON account_audit WHEN NEW.action='trial-start' BEGIN SELECT RAISE(ABORT,'synthetic audit denied'); END;"]);try{const before=snapshot();assert.notEqual((await start(s)).status,200);assert.deepEqual(snapshot(),before);}finally{d1(['--command','DROP TRIGGER s1b_fail_audit;']);}});
