 await test('deletion revokes sessions and strips old email association; fresh registration marker never extends',async()=>{const address=email();const s=await signedIn(address);assert.equal((await start(s)).status,200);const h=rows(`SELECT email_hmac FROM accounts WHERE account_id='${s.accountID}'`)[0].email_hmac;assert.equal((await deletion(s)).status,200);const old=rows(`SELECT * FROM accounts WHERE account_id='${s.accountID}'`)[0];assert.equal(old.email_hmac,'deleted:'+s.accountID);assert.equal(old.revoked_at,initial);assert.equal((await post('authenticate',credential(s))).status,401);const marker=rows(`SELECT * FROM trial_markers WHERE email_hmac='${h}'`)[0];assert.equal(marker.original_deleted_at,initial);assert.equal(marker.expires_at,1823270400);const fresh=await signedIn(address,'app-sign-in',initial+60);assert.notEqual(fresh.accountID,s.accountID);assert.notEqual((await start(fresh,'blocked',initial+60)).status,200);assert.equal((await deletion(fresh,initial+60)).status,200);assert.deepEqual(rows(`SELECT * FROM trial_markers WHERE email_hmac='${h}'`)[0],marker);});
 for(const delta of [-1,0,1])await test(`fresh actual sign-in trial at fixed marker boundary ${delta}`,async()=>{const address=email();const s=await signedIn(address);assert.equal((await start(s)).status,200);assert.equal((await deletion(s)).status,200);const t=1823270400+delta;const fresh=await signedIn(address,'app-sign-in',t);const r=await start(fresh,'boundary',t);assert.equal(r.status,delta<0?409:200);if(delta>=0){assert.equal(r.body.startedAt,t);assert.equal(r.body.expiresAt,t+1209600);}assert.equal(rows(`SELECT trial_started_at FROM entitlement_sources WHERE account_id='${s.accountID}'`)[0].trial_started_at,initial);});
 await test('cleanup dry run then actual challenge/session/retry/audit TTLs is idempotent',async()=>{const s=await signedIn();assert.equal((await start(s)).status,200);const now=initial+800*86400;const before=snapshot();const dry=await cleanup(s,now,true);assert.equal(dry.status,200);assert.ok(Number(dry.body.eligible)>0);assert.deepEqual(snapshot(),before);const first=await cleanup(s,now);assert.equal(first.status,200);assert.equal(rows(`SELECT * FROM challenges WHERE email_hmac=(SELECT email_hmac FROM accounts WHERE account_id='${s.accountID}')`).length,0);assert.equal(rows(`SELECT * FROM sessions WHERE account_id='${s.accountID}'`).length,0);assert.equal(rows(`SELECT * FROM trial_requests WHERE account_id='${s.accountID}'`).length,0);assert.equal(rows(`SELECT COUNT(*) AS n FROM accounts WHERE account_id='${s.accountID}'`)[0].n,1);const second=await cleanup(s,now);assert.equal(second.status,200);assert.equal(second.body.deleted,0);});
 for(const protection of ['maxGrant','intent','reconciliation','hold','unknown','financial'])await test(`cleanup preserves actual histories with ${protection}`,async()=>{const s=await signedIn();const now=initial+800*86400;if(protection==='maxGrant')d1(['--command',`INSERT INTO lease_heads(activation_id,account_id,device_key_sha256,activation_revision,max_grant_permitted_until,commit_nonce) VALUES('${(100000+requestCounter).toString(16).padStart(32,'0')}','${s.accountID}','${'c'.repeat(64)}',1,${now+1},'seed');`]);else d1(['--command',`INSERT INTO retention_rows VALUES('protect-${requestCounter}','${s.accountID}','${JSON.stringify({category:protection==='financial'?'financial-ledger':protection==='unknown'?'unknown':'active-account'})}',NULL,${protection==='intent'?1:0},${protection==='reconciliation'?1:0},${protection==='hold'?1:0},'seed');`]);const before=snapshot();const r=await cleanup(s,now);assert.equal(r.status,200);assert.equal(r.body.deleted,0);assert.deepEqual(snapshot(),before);});
 await test('cleanup/audited lease refresh race cannot erase an outstanding maximum grant',async()=>{const s=await signedIn();assert.equal((await start(s)).status,200);const activationID='b'.repeat(32);d1(['--command',`INSERT INTO lease_heads(activation_id,account_id,device_key_sha256,activation_revision,commit_nonce) VALUES('${activationID}','${s.accountID}','${'c'.repeat(64)}',1,'seed');`]);const g=guard(s);const results=await Promise.all([post('s1b/issue',{credential:credential(s),guard:{...g,commitNonce:'issue-race'},activationID}),cleanup(s,initial+86400,false,{...g,commitNonce:'cleanup-race'})]);assert.ok(results.some(r=>r.status===200));if(results[0].status===200&&results[1].status===200)assert.equal(results[1].body.deleted,0);const head=rows(`SELECT * FROM lease_heads WHERE activation_id='${activationID}'`)[0];assert.ok(head);if(results[0].status===200){assert.equal(head.sequence,1);assert.equal(head.max_grant_permitted_until,initial+1209600);assert.ok(results[0].body.envelope);} });
 await test('lost issuance audit returns no bytes and rolls back sequence/max bounds',async()=>{const s=await signedIn();assert.equal((await start(s)).status,200);const activationID='c'.repeat(32);d1(['--command',`INSERT INTO lease_heads(activation_id,account_id,device_key_sha256,activation_revision,commit_nonce) VALUES('${activationID}','${s.accountID}','${'c'.repeat(64)}',1,'seed');`]);d1(['--command',"CREATE TRIGGER s1b_fail_issue BEFORE INSERT ON account_audit WHEN NEW.action='lease-issue' BEGIN SELECT RAISE(ABORT,'synthetic audit denied'); END;"]);try{const before=snapshot();const r=await post('s1b/issue',{credential:credential(s),guard:guard(s),activationID});assert.notEqual(r.status,200);assert.equal(r.body.envelope,undefined);assert.deepEqual(snapshot(),before);}finally{d1(['--command','DROP TRIGGER s1b_fail_issue;']);}});
 await test('refresh/release/cleanup races retain maximum historical bound and released identity',async()=>{const s=await signedIn();assert.equal((await start(s)).status,200);const activationID='d'.repeat(32);const oldMaximum=initial+1209600+100;d1(['--command',`INSERT INTO lease_heads(activation_id,account_id,device_key_sha256,activation_revision,sequence,last_grant_state,last_grant_issued_at,last_grant_permitted_until,last_grant_hard_end,max_grant_permitted_until,commit_nonce) VALUES('${activationID}','${s.accountID}','${'c'.repeat(64)}',1,7,'trial',${initial-1},${oldMaximum},${oldMaximum},${oldMaximum},'seed');`]);const g=guard(s);const results=await Promise.all([post('s1b/issue',{credential:credential(s),guard:{...g,commitNonce:'refresh-race'},activationID}),post('s1b/release',{credential:credential(s),guard:{...g,commitNonce:'release-race'},activationID}),cleanup(s,initial+86400,false,{...g,commitNonce:'cleanup3-race'})]);assert.equal(results.slice(0,2).filter(r=>r.status===200).length,1);if(results[2].status===200)assert.equal(results[2].body.deleted,0);const h=rows(`SELECT * FROM lease_heads WHERE activation_id='${activationID}'`)[0];assert.ok(h);assert.equal(h.max_grant_permitted_until,oldMaximum);if(results[1].status===200){assert.equal(h.released_at,initial);const before=snapshot();const refused=await post('s1b/issue',{credential:credential(s),guard:guard(s),activationID});if(refused.status===200){const e=JSON.parse(String(refused.body.envelope));const c=JSON.parse(Buffer.from(e.payload,'base64').toString());assert.equal(c.state,'revoked');assert.equal(c.permittedUntil,c.issuedAt);assert.equal(c.hardEnd,c.issuedAt);}else{assert.equal(refused.body.envelope,undefined);assert.deepEqual(snapshot(),before);}}});
