 await test('audit/retry cleanup cannot make earlier S1b nonce reusable',async()=>{const s=await signedIn();const first=guard(s,'historical-nonce');assert.equal((await start(s,'first',initial,first)).status,200);const activationID='e'.repeat(32);d1(['--command',`INSERT INTO lease_heads(activation_id,account_id,device_key_sha256,activation_revision,commit_nonce) VALUES('${activationID}','${s.accountID}','${'c'.repeat(64)}',1,'seed');`]);assert.equal((await post('s1b/release',{credential:credential(s),guard:guard(s,'second-nonce'),activationID})).status,200);assert.equal((await cleanup(s,initial+800*86400)).status,200);assert.equal(rows(`SELECT COUNT(*) AS n FROM account_nonce_history WHERE account_id='${s.accountID}' AND commit_nonce='historical-nonce'`)[0].n,1);const before=snapshot();const reused=await cleanup(s,initial+800*86400,false,guard(s,'historical-nonce'));assert.equal(reused.status,409);assert.deepEqual(snapshot(),before);});

